/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 20.01.25
/// </summary>
class NDXUmsatzCSRefreshService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 20.01.25
/// </summary>
/// <param name = "_contract">NDXUmsatzCSRefreshContract</param>
public void process(NDXUmsatzCSRefreshContract _contract)
{
    NDXUmsatzRefreshClass umsatzRefreshClass = NDXUmsatzRefreshClass::constructFromContract(_contract);
    NDXUmsatzCSRefreshType umsatzCSRefreshType;
    NDXUmsatzAbschluss abschluss;
    NDXMonthBE liveSalesMonth;
    NDXJahr liveSalesYear;

    if(this.isExecutingInBatch())
    {
        umsatzRefreshClass.parmlisBatch(true);
    }
    umsatzCSRefreshType = _contract.parmumsatzCSRefreshType();

    switch(umsatzCSRefreshType)
    {

        case NDXUmsatzCSRefreshType::SalesGroup:
            if(_contract.parmSalesGroup())
            {
                umsatzRefreshClass.parmSalesGroup(_contract.parmSalesGroup());
            }
            if(_contract.parmDataVersion())
            {
                umsatzRefreshClass.parmDataVersion(_contract.parmDataVersion());
            }
            umsatzRefreshClass.parmLBuildSalesGroup(_contract.parmLBuildSalesGroup());            
            break;

        case NDXUmsatzCSRefreshType::Alliance :
            umsatzRefreshClass.parmLBuildAlliance(true);

            if(_contract.parmAlliance())
            {
                umsatzRefreshClass.parmAlliance(_contract.parmAlliance());
            }
            else
            {
                umsatzRefreshClass.parmLBuildVerband(NoYes::Yes);
            }

            if(_contract.parmDataVersion())
            {
                umsatzRefreshClass.parmDataVersion(_contract.parmDataVersion());
            }
            break;

        case NDXUmsatzCSRefreshType::PrepareLiveData:                            
            abschluss = NDXUmsatzAbschluss::construct(NDXUmsatzParametersGlobal::findParametersMaster().BasisDate4Close, 0);
            liveSalesMonth  = abschluss.getMonthBE();
            liveSalesYear   = abschluss.parmJahr();

            umsatzRefreshClass.parmLiveSalesMonth(liveSalesMonth);
            umsatzRefreshClass.parmLiveSalesYear(liveSalesYear);
            umsatzRefreshClass.parmlLiveSales(NoYes::Yes);
            umsatzRefreshClass.parmlfillKumUmsCust(NoYes::No);
            break;
        case NDXUmsatzCSRefreshType::CopyToKumUms:
            abschluss = NDXUmsatzAbschluss::construct(NDXUmsatzParametersGlobal::findParametersMaster().BasisDate4Close, 0);
            liveSalesMonth  = abschluss.getMonthBE();
            liveSalesYear   = abschluss.parmJahr();

            umsatzRefreshClass.parmLiveSalesMonth(liveSalesMonth);
            umsatzRefreshClass.parmLiveSalesYear(liveSalesYear);
            umsatzRefreshClass.parmlLiveSales(NoYes::No);
            umsatzRefreshClass.parmlfillKumUmsCust(NoYes::Yes);
            break;
    }

    umsatzRefreshClass.run();
}
